     const F=['круг','квадрат','треугольник','овал'], [A,Bf,Cf]=r.sample(F,3), P=r.pick([[A,Bf],[A,A,Bf],[A,Bf,Bf],[A,Bf,Cf]]), L=r.int(6,8), s=[]; for (let i=0;i<=L;i++) s.push(P[i%P.length]);
